import React, { useState } from "react";
// import {AiOutlineHtml5} from 'react-icons/ai'
// import {TbBrandCss3} from 'react-icons/tb'
// import {FaPhp} from 'react-icons/fa'
// import {RiBootstrapLine} from 'react-icons/ri'
// import {BiLogoFirebase, BiLogoJavascript, BiLogoReact, BiLogoGithub} from 'react-icons/bi'
// import { Carousel, IconButton } from "@material-tailwind/react";
import Details from "./Details";
import { Element } from "react-scroll";
import {
  Tabs,
  TabsHeader,
  TabsBody,
  Tab,
  TabPanel,
} from "@material-tailwind/react";

import "../App.css";

const Projects = () => {
  const [activeTab, setActiveTab] = useState("reactjs");

  return (
    <Element id="projectsPage" name="projectsPage" className="relative ">
      <div className="">
        <section className="flex flex-col w-screen my-5 ">
          <span className="flex justify-center mx-6 my-10 text-orange-500 underline md:mx-24 lg:mx-36 ">
            <h1 className="text-4xl font-bold lg:text-4xl">PROJECTS</h1>
          </span>

          <Tabs
            value={activeTab}
            className=" mx-2 md:mx-24 lg:mx-28 mb-10 z-[998] custom-tabs "
          >
            <TabsHeader className="flex items-center rounded-b-none ">
              {Details.map(({ label, value }) => (
                <Tab
                  key={value}
                  value={value}
                  onClick={() => setActiveTab(value)}
                  className={`${
                    activeTab === value
                      ? "text-orange-500 font-bold "
                      : "text-black "
                  } `}
                >
                  <span className="flex text-sm font-bold font-kanit md:text-lg ">
                    {label}
                  </span>
                </Tab>
              ))}
            </TabsHeader>

            <TabsBody className="">
              {Details.map(({ value, desc, imgSrc }) => (
                <TabPanel
                  key={value}
                  value={value}
                  className="font-normal text-black bg-gray-400 text-md rounded-b-2xl font-kanit "
                >
                  <div className="text-xs text-gray-900 md:text-lg">{desc}</div>
                </TabPanel>
              ))}
            </TabsBody>

            <TabsBody className="">
              {Details.map(({ value, desc, imgSrc }) => (
                <TabPanel key={value} value={value} className="text-white ">
                  <div className="grid object-cover w-full grid-cols-2 gap-4 md:grid-cols-3 lg:grid-cols-4 md:mx-0 lg:mx-0 ">
                    {Array.isArray(imgSrc) &&
                      imgSrc.map((src, index) => (
                        <div className="border-b-2 border-orange-500 shadow-md shadow-orange-500 rounded-xl ">
                          <img
                            key={index}
                            src={src}
                            alt={`${index}`}
                            className="w-full h-full duration-500 border-2 rounded-xl hover:scale-105"
                          />
                        </div>
                      ))}
                  </div>
                </TabPanel>
              ))}
            </TabsBody>
          </Tabs>
        </section>
      </div>
    </Element>
  );
};

export default Projects;
